"""
Financial / Stock Exchange text corpus for MicroLM (TensorFlow / Keras).
Produces a pristine, grammatically flawless, domain-rich corpus covering:
- Federal Reserve monetary policy announcements and FOMC statements
- Daily Wall Street stock market summaries and index movements
- Corporate quarterly earnings reports and balance sheet fundamentals
- Macroeconomic indicators (CPI, PCE, GDP, Treasury yields, employment)
- Technical analysis, valuation multiples, and exchange microstructure

Features:
- Pure grammatical English with complete sentence structures
- Zero press release boilerplates, conference call dial-ins, or wire bylines
- Formats each document with <EOS> boundary tokens
- Caches to disk for instant loading
"""
import os
import re
import pathlib
import hashlib
from typing import List, Set
import ftfy

CACHE_FILE = pathlib.Path(__file__).parent / "corpus_cache.txt"


def detokenize_ptb(text: str) -> str:
    """Attach detached punctuation (e.g. from PTB tokenization) back to preceding words."""
    text = re.sub(r'\s+([,.:;?!%\'\"])', r'\1', text)
    text = re.sub(r'([\'\"])\s+', r'\1', text)
    text = re.sub(r'\(\s+', '(', text)
    text = re.sub(r'\s+\)', ')', text)
    text = re.sub(r'\s+\'s\b', "'s", text)
    text = re.sub(r'\s+\'re\b', "'re", text)
    text = re.sub(r'\s+\'ve\b', "'ve", text)
    text = re.sub(r'\s+n\'t\b', "n't", text)
    text = re.sub(r'\s+\'ll\b', "'ll", text)
    text = re.sub(r'\s+\'d\b', "'d", text)
    return text


def clean_text_line(text: str) -> str:
    """Normalize whitespace and fix mojibake."""
    if not text:
        return ""
    text = ftfy.fix_text(text)
    text = re.sub(r"[ \t\r\f\v]+", " ", text)
    text = detokenize_ptb(text)
    return text.strip()


