def get_corpus(use_cache: bool = True) -> str:
    """
    Generate or load the clean, comprehensive financial corpus.
    All documents end with <EOS>.
    """
    clean_marker = "# CLEAN_CORPUS_V3\n"

    if use_cache and CACHE_FILE.exists():
        try:
            cached_text = CACHE_FILE.read_text(encoding="utf-8")
            if cached_text.startswith(clean_marker) and "<EOS>" in cached_text and len(cached_text) > 300_000:
                num_docs = cached_text.count("<EOS>")
                char_count = len(cached_text)
                word_count = len(cached_text.split())
                print(f"[Corpus] Loaded clean cached corpus: {num_docs:,} docs, {char_count:,} chars, ~{word_count:,} words")
                return cached_text
        except Exception as e:
            print(f"[Corpus] Error reading cache: {e}")

    # Build fresh pristine documents
    print("[Corpus] Generating fresh pristine financial documents...")
    base_docs = build_pristine_financial_documents()
    print(f"[Corpus] Built {len(base_docs):,} unique high-quality financial documents.")

    # Upweight 4x to ensure sufficient sequence depth and dense n-gram exposure
    all_docs = []
    for _ in range(4):
        all_docs.extend(base_docs)

    formatted_corpus = clean_marker + "\n".join(f"{doc} <EOS>" for doc in all_docs)
    char_count = len(formatted_corpus)
    word_count = len(formatted_corpus.split())
    doc_count = len(all_docs)

    print(f"\n[Corpus] === Cleaned Corpus Summary ===")
    print(f"[Corpus]   Total documents:  {doc_count:,}")
    print(f"[Corpus]   Total characters: {char_count:,}")
    print(f"[Corpus]   Total words:      ~{word_count:,}")
    print(f"[Corpus]   Format:           1 document per line, ending with <EOS>")

    # Save to disk cache
    try:
        CACHE_FILE.parent.mkdir(parents=True, exist_ok=True)
        CACHE_FILE.write_text(formatted_corpus, encoding="utf-8")
        print(f"[Corpus] Saved cleaned corpus cache to {CACHE_FILE}")
    except Exception as e:
        print(f"[Corpus] Could not save cache: {e}")

    return formatted_corpus


if __name__ == "__main__":
    c = get_corpus(use_cache=False)
    lines = c.splitlines()
    print(f"\nPreview of first 3 documents:")
    for i, line in enumerate(lines[:3]):
        print(f"Doc {i+1} ({len(line)} chars): {line[:120]}...")
